fn build_remote_hydration_http_client() -> eyre::Result<reqwest::blocking::Client> {
    reqwest::blocking::Client::builder()
        .connect_timeout(Duration::from_secs(5))
        .timeout(Duration::from_secs(30))
        .redirect(reqwest::redirect::Policy::none())
        .retry(reqwest::retry::never())
        .build()
        .wrap_err("build Soracloud remote hydration HTTP client")
}
fn read_soracloud_http_response_body_bounded(
    reader: &mut impl io::Read,
    declared_length: Option<u64>,
    maximum_bytes: u64,
) -> eyre::Result<Vec<u8>> {
    if maximum_bytes == 0 {
        eyre::bail!("Soracloud HTTP response byte limit must be positive");
    }
    if let Some(length) = declared_length
        && length > maximum_bytes
    {
        eyre::bail!(
            "Soracloud HTTP response Content-Length {length} exceeds the {maximum_bytes}-byte limit"
        );
    }
    let maximum = usize::try_from(maximum_bytes)
        .wrap_err("Soracloud HTTP response byte limit does not fit this host")?;
    let initial_capacity = declared_length
        .and_then(|length| usize::try_from(length).ok())
        .unwrap_or(SORACLOUD_HTTP_RESPONSE_INITIAL_ALLOCATION_BYTES)
        .min(SORACLOUD_HTTP_RESPONSE_INITIAL_ALLOCATION_BYTES)
        .min(maximum);
    let mut body = Vec::new();
    body.try_reserve_exact(initial_capacity)
        .wrap_err("reserve initial Soracloud HTTP response buffer")?;
    let mut buffer = [0_u8; SORACLOUD_HTTP_RESPONSE_READ_BUFFER_BYTES];
    loop {
        let remaining = maximum
            .checked_sub(body.len())
            .ok_or_else(|| eyre::eyre!("Soracloud HTTP response body length overflow"))?;
        let read_capacity = remaining.min(buffer.len());
        if read_capacity == 0 {
            let read = read_soracloud_http_response_chunk(reader, &mut buffer[..1])?;
            if read == 0 {
                break;
            }
            eyre::bail!("Soracloud HTTP response body exceeds the {maximum_bytes}-byte limit");
        }
        let read = read_soracloud_http_response_chunk(reader, &mut buffer[..read_capacity])?;
        if read == 0 {
            break;
        }
        let required_len = body
            .len()
            .checked_add(read)
            .ok_or_else(|| eyre::eyre!("Soracloud HTTP response body length overflow"))?;
        reserve_soracloud_http_response_capacity(&mut body, required_len, maximum)?;
        body.extend_from_slice(&buffer[..read]);
    }
    let actual_length = u64::try_from(body.len()).unwrap_or(u64::MAX);
    if let Some(length) = declared_length
        && length != actual_length
    {
        eyre::bail!(
            "Soracloud HTTP response body length {actual_length} does not match Content-Length {length}"
        );
    }
    Ok(body)
}
fn reserve_soracloud_http_response_capacity(
    body: &mut Vec<u8>,
    required_len: usize,
    maximum: usize,
) -> eyre::Result<()> {
    if required_len > maximum {
        eyre::bail!("Soracloud HTTP response reservation exceeds its byte limit");
    }
    if body.capacity() >= required_len {
        return Ok(());
    }
    let growth_target = body
        .capacity()
        .max(1)
        .saturating_mul(2)
        .max(required_len)
        .min(maximum);
    body.try_reserve_exact(growth_target.saturating_sub(body.len()))
        .wrap_err("reserve Soracloud HTTP response buffer")
}
fn read_soracloud_http_response_chunk(
    reader: &mut impl io::Read,
    buffer: &mut [u8],
) -> eyre::Result<usize> {
    loop {
        match reader.read(buffer) {
            Ok(read) if read <= buffer.len() => return Ok(read),
            Ok(read) => {
                eyre::bail!(
                    "Soracloud HTTP response reader reported {read} bytes for a {}-byte buffer",
                    buffer.len()
                );
            }
            Err(error) if error.kind() == io::ErrorKind::Interrupted => {}
            Err(error) => return Err(error).wrap_err("read Soracloud HTTP response body"),
        }
    }
}
fn read_soracloud_http_response_bounded(
    mut response: reqwest::blocking::Response,
    maximum_bytes: u64,
    label: &str,
) -> eyre::Result<Vec<u8>> {
    let declared_length = response.content_length();
    read_soracloud_http_response_body_bounded(&mut response, declared_length, maximum_bytes)
        .wrap_err_with(|| format!("read bounded {label} response"))
}
fn open_soracloud_regular_file_no_follow(
    path: &Path,
    label: &str,
) -> io::Result<(fs::File, fs::Metadata)> {
    let named = fs::symlink_metadata(path)?;
    if named.file_type().is_symlink() || !named.is_file() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{label} {} must be a regular file", path.display()),
        ));
    }
    #[cfg(unix)]
    if named.nlink() != 1 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "{label} {} must have exactly one hard link, found {}",
                path.display(),
                named.nlink()
            ),
        ));
    }
    let mut options = fs::OpenOptions::new();
    options.read(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        options.custom_flags(rustix::fs::OFlags::NOFOLLOW.bits() as i32);
    }
    #[cfg(windows)]
    {
        use std::os::windows::fs::OpenOptionsExt as _;
        const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
        options.custom_flags(FILE_FLAG_OPEN_REPARSE_POINT);
    }
    let file = options.open(path)?;
    let opened = file.metadata()?;
    if !same_soracloud_regular_file(&named, &opened) {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{label} {} changed while it was opened", path.display()),
        ));
    }
    Ok((file, opened))
}
fn same_soracloud_regular_file(left: &fs::Metadata, right: &fs::Metadata) -> bool {
    if !left.is_file() || !right.is_file() || left.len() != right.len() {
        return false;
    }
    #[cfg(unix)]
    {
        left.dev() == right.dev()
            && left.ino() == right.ino()
            && left.nlink() == right.nlink()
            && left.mtime() == right.mtime()
            && left.mtime_nsec() == right.mtime_nsec()
            && left.ctime() == right.ctime()
            && left.ctime_nsec() == right.ctime_nsec()
    }
    #[cfg(not(unix))]
    {
        left.modified().ok() == right.modified().ok()
    }
}
fn read_soracloud_regular_file_bounded(
    path: &Path,
    maximum_bytes: u64,
    label: &str,
) -> io::Result<Vec<u8>> {
    if maximum_bytes == 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("{label} byte limit must be positive"),
        ));
    }
    let (mut file, fingerprint) = open_soracloud_regular_file_no_follow(path, label)?;
    if fingerprint.len() > maximum_bytes {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "{label} {} requires {} bytes, exceeding the {maximum_bytes}-byte limit",
                path.display(),
                fingerprint.len()
            ),
        ));
    }
    let capacity = usize::try_from(fingerprint.len()).map_err(|_| {
        io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{label} {} is too large to address", path.display()),
        )
    })?;
    let mut payload = Vec::new();
    payload.try_reserve_exact(capacity).map_err(|error| {
        io::Error::other(format!(
            "reserve {label} {} bounded buffer: {error}",
            path.display()
        ))
    })?;
    std::io::Read::by_ref(&mut file)
        .take(maximum_bytes.saturating_add(1))
        .read_to_end(&mut payload)?;
    let observed = u64::try_from(payload.len()).unwrap_or(u64::MAX);
    if observed > maximum_bytes {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "{label} {} exceeds the {maximum_bytes}-byte limit",
                path.display()
            ),
        ));
    }
    let opened_after = file.metadata()?;
    let named_after = fs::symlink_metadata(path)?;
    if observed != fingerprint.len()
        || !same_soracloud_regular_file(&fingerprint, &opened_after)
        || !same_soracloud_regular_file(&opened_after, &named_after)
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("{label} {} changed while it was read", path.display()),
        ));
    }
    Ok(payload)
}
fn read_soracloud_regular_text_bounded(
    path: &Path,
    maximum_bytes: u64,
    label: &str,
) -> io::Result<String> {
    String::from_utf8(read_soracloud_regular_file_bounded(
        path,
        maximum_bytes,
        label,
    )?)
    .map_err(|error| io::Error::new(io::ErrorKind::InvalidData, error))
}
/// Runtime-manager configuration derived from the explicit Soracloud runtime settings.
#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct SoracloudRuntimeManagerConfig {
    /// Whether runtime production posture checks are enabled.
    pub production_mode: bool,
    /// Root directory for local runtime materialization state.
    pub state_dir: PathBuf,
    /// Reconciliation cadence against authoritative state.
    pub reconcile_interval: Duration,
    /// Reserved concurrency budget for future hydration workers.
    pub hydration_concurrency: NonZeroUsize,
    /// Configured artifact-cache budgets for the embedded runtime manager.
    pub cache_budgets: iroha_config::parameters::actual::SoracloudRuntimeCacheBudgets,
    /// Mutable `Inrou` microVM hosting limits.
    pub inrou: iroha_config::parameters::actual::SoracloudRuntimeInrou,
    /// Runtime-originated transaction submission settings.
    pub submission: iroha_config::parameters::actual::SoracloudRuntimeSubmission,
    /// Outbound egress policy for embedded runtimes.
    pub egress: iroha_config::parameters::actual::SoracloudRuntimeEgress,
    /// Hugging Face importer and inference bridge settings.
    pub hf: iroha_config::parameters::actual::SoracloudRuntimeHuggingFace,
    /// Local validator account used to enforce authoritative HF placement assignments.
    pub local_validator_account_id: Option<AccountId>,
    /// Local peer identifier used to confirm authoritative HF placement assignments.
    pub local_peer_id: Option<String>,
    /// Test-only admission for exercising the unconfined implementation without
    /// exposing a shipping configuration or programmatic bypass.
    #[cfg(test)]
    allow_unconfined_inrou: bool,
}
/// Internal sink used by the runtime manager to enqueue authoritative Soracloud mutations.
pub(crate) trait SoracloudRuntimeMutationSink: Send + Sync {
    /// Revalidate the production signer boundary before manager startup.
    ///
    /// Non-production recording and test sinks deliberately fail this check.
    fn ensure_production_qualified(&self) -> eyre::Result<()> {
        eyre::bail!("mutation sink is not backed by a qualified production signer")
    }
    /// Submit one authoritative Soracloud instruction through the normal transaction pipeline.
    fn submit_instruction(
        &self,
        instruction: InstructionBox,
        endpoint: &'static str,
    ) -> eyre::Result<()>;
    /// Submit an authoritative model-host heartbeat using the sink's configured validator authority.
    fn submit_model_host_heartbeat(
        &self,
        validator_account_id: &AccountId,
        heartbeat_expires_at_ms: u64,
    ) -> eyre::Result<()>;
    /// Submit or refresh the authoritative Inrou host advert using the sink's configured validator authority.
    fn submit_inrou_host_capability(
        &self,
        capability: &SoraInrouHostCapabilityRecordV1,
    ) -> eyre::Result<()>;
    /// Withdraw this sink's authoritative Inrou host advert.
    fn submit_inrou_host_withdrawal(&self, _validator_account_id: &AccountId) -> eyre::Result<()> {
        eyre::bail!("mutation sink does not support Inrou host withdrawal")
    }
    /// Submit an authoritative Inrou placement reconciliation request.
    fn submit_inrou_placement_reconcile(&self) -> eyre::Result<()> {
        self.submit_instruction(
            InstructionBox::from(isi::soracloud::ReconcileSoracloudInrouPlacements),
            "/internal/soracloud/runtime/inrou-placement-reconcile",
        )
    }
}
/// Queue-backed mutation sink used by `irohad` to report runtime-originated Soracloud health events.
#[derive(Clone)]
pub(crate) struct QueuedSoracloudRuntimeMutationSink {
    queue: Arc<Queue>,
    state: Arc<State>,
    authority: AccountId,
    binding: crate::soracloud_runtime_signer::SoracloudRuntimeSignerBindingV1,
    signer: Arc<dyn crate::soracloud_runtime_signer::SoracloudRuntimeMutationSignerV1>,
    submission: iroha_config::parameters::actual::SoracloudRuntimeSubmission,
}
impl QueuedSoracloudRuntimeMutationSink {
    /// Construct a queue-backed sink using the exact configured external authority.
    ///
    /// # Errors
    ///
    /// Returns an error when the public binding is missing or invalid, or when
    /// the injected provider is unavailable, substituted, stale, revoked, or
    /// test-marked.
    pub(crate) fn new(
        queue: Arc<Queue>,
        state: Arc<State>,
        signer: Arc<dyn crate::soracloud_runtime_signer::SoracloudRuntimeMutationSignerV1>,
        submission: iroha_config::parameters::actual::SoracloudRuntimeSubmission,
    ) -> eyre::Result<Self> {
        let configured = submission.signer.as_ref().ok_or_else(|| {
            eyre::eyre!("queue-backed mutation sink requires a configured signer binding")
        })?;
        let binding =
            crate::soracloud_runtime_signer::SoracloudRuntimeSignerBindingV1::try_from_config(
                configured,
            )
            .map_err(|error| eyre::eyre!("invalid configured signer binding: {error:?}"))?;
        let signer = crate::soracloud_runtime_signer::qualify_soracloud_runtime_mutation_signer_v1(
            binding.clone(),
            signer,
        )
        .map_err(|error| eyre::eyre!("runtime signer qualification failed: {error:?}"))?;
        let authority = binding.authority().clone();
        Ok(Self {
            queue,
            state,
            authority,
            binding,
            signer,
            submission,
        })
    }
}
impl SoracloudRuntimeMutationSink for QueuedSoracloudRuntimeMutationSink {
    fn ensure_production_qualified(&self) -> eyre::Result<()> {
        crate::soracloud_runtime_signer::qualify_soracloud_runtime_mutation_signer_v1(
            self.binding.clone(),
            Arc::clone(&self.signer),
        )
        .map(|_| ())
        .map_err(|error| eyre::eyre!("runtime signer is no longer production-qualified: {error:?}"))
    }
    fn submit_instruction(
        &self,
        instruction: InstructionBox,
        endpoint: &'static str,
    ) -> eyre::Result<()> {
        let mut payload = build_soracloud_runtime_submission_payload(
            *self.state.network_id_ref(),
            self.authority.clone(),
            instruction,
            self.submission.fee_payment_intent(),
            endpoint,
        )?;
        let route = self
            .queue
            .route_payload_with_state(&payload, self.state.as_ref())
            .wrap_err_with(|| {
                format!("route internal Soracloud runtime mutation at `{endpoint}`")
            })?;
        let latest_header = self.state.latest_block_header_fast();
        let observation_time_ms = latest_header
            .as_ref()
            .map_or(0, |header| header.creation_time_ms);
        let next_block_height = latest_header
            .as_ref()
            .map_or(1, |header| header.height().get().saturating_add(1));
        let nexus = self.state.nexus_snapshot();
        let pipeline = self.state.pipeline_snapshot();
        let quote = {
            let world = self.state.world_view();
            quote_nexus_fee_admission_draft(
                &world,
                &nexus,
                &pipeline,
                &payload,
                observation_time_ms,
                next_block_height,
                Some(route.dataspace_id),
            )
        }
        .map_err(|error| {
            eyre::eyre!("quote internal Soracloud runtime mutation at `{endpoint}`: {error:?}")
        })?;
        payload.fee_payment = quote.recommended_intent;
        let tx = self
            .signer
            .sign_transaction(payload)
            .map_err(|error| {
                eyre::eyre!(
                    "external signer refused internal Soracloud runtime mutation at `{endpoint}`: {error:?}"
                )
            })?;
        let (max_clock_drift, transaction_params, crypto) = {
            let world = self.state.world_view();
            let params = world.parameters();
            (
                params.sumeragi().max_clock_drift(),
                params.transaction(),
                self.state.crypto(),
            )
        };
        let accepted = AcceptedTransaction::accept(
            tx,
            self.state.network_id_ref(),
            max_clock_drift,
            transaction_params,
            crypto.as_ref(),
        )
        .wrap_err_with(|| format!("accept internal Soracloud runtime mutation at `{endpoint}`"))?;
        self.queue
            .push_with_lane_with_state(accepted, self.state.as_ref())
            .map(|_| ())
            .map_err(|failure| {
                eyre::eyre!(
                    "enqueue internal Soracloud runtime mutation at `{endpoint}`: {}",
                    failure.err
                )
            })
    }
    fn submit_model_host_heartbeat(
        &self,
        validator_account_id: &AccountId,
        heartbeat_expires_at_ms: u64,
    ) -> eyre::Result<()> {
        if *validator_account_id != self.authority {
            eyre::bail!(
                "runtime model-host heartbeat validator `{validator_account_id}` does not match sink authority `{}`",
                self.authority
            );
        }
        let provenance_preimage = encode_model_host_heartbeat_provenance_payload(
            validator_account_id,
            heartbeat_expires_at_ms,
        )
        .wrap_err("encode runtime model-host heartbeat provenance payload")?;
        let instruction = InstructionBox::from(isi::soracloud::HeartbeatSoracloudModelHost {
            validator_account_id: validator_account_id.clone(),
            heartbeat_expires_at_ms,
            provenance: ManifestProvenance {
                signer: self
                    .signer
                    .public_key()
                    .map_err(|error| eyre::eyre!("probe runtime signer key: {error:?}"))?,
                signature: self
                    .signer
                    .sign_provenance(
                        iroha_data_model::soracloud::SoracloudRuntimeProvenancePurposeV1::ModelHostHeartbeat,
                        &provenance_preimage,
                    )
                    .map_err(|error| {
                        eyre::eyre!(
                            "external signer refused model-host heartbeat provenance: {error:?}"
                        )
                    })?,
            },
        });
        self.submit_instruction(
            instruction,
            "/internal/soracloud/runtime/model-host-heartbeat",
        )
    }
    fn submit_inrou_host_capability(
        &self,
        capability: &SoraInrouHostCapabilityRecordV1,
    ) -> eyre::Result<()> {
        if capability.validator_account_id != self.authority {
            eyre::bail!(
                "runtime Inrou host advert validator `{}` does not match sink authority `{}`",
                capability.validator_account_id,
                self.authority
            );
        }
        let provenance_preimage = encode_inrou_host_advertise_provenance_payload(capability)
            .wrap_err("encode runtime Inrou host advert provenance payload")?;
        let instruction = InstructionBox::from(isi::soracloud::AdvertiseSoracloudInrouHost {
            capability: capability.clone(),
            provenance: ManifestProvenance {
                signer: self
                    .signer
                    .public_key()
                    .map_err(|error| eyre::eyre!("probe runtime signer key: {error:?}"))?,
                signature: self
                    .signer
                    .sign_provenance(
                        iroha_data_model::soracloud::SoracloudRuntimeProvenancePurposeV1::InrouHostAdvert,
                        &provenance_preimage,
                    )
                    .map_err(|error| {
                        eyre::eyre!(
                            "external signer refused Inrou host-advert provenance: {error:?}"
                        )
                    })?,
            },
        });
        self.submit_instruction(instruction, "/internal/soracloud/runtime/inrou-host-advert")
    }
    fn submit_inrou_host_withdrawal(&self, validator_account_id: &AccountId) -> eyre::Result<()> {
        if *validator_account_id != self.authority {
            eyre::bail!(
                "runtime Inrou host withdrawal validator `{validator_account_id}` does not match sink authority `{}`",
                self.authority
            );
        }
        let provenance_preimage =
            encode_inrou_host_withdraw_provenance_payload(validator_account_id)
                .wrap_err("encode runtime Inrou host withdrawal provenance payload")?;
        let instruction = InstructionBox::from(isi::soracloud::WithdrawSoracloudInrouHost {
            validator_account_id: validator_account_id.clone(),
            provenance: ManifestProvenance {
                signer: self
                    .signer
                    .public_key()
                    .map_err(|error| eyre::eyre!("probe runtime signer key: {error:?}"))?,
                signature: self
                    .signer
                    .sign_provenance(
                        iroha_data_model::soracloud::SoracloudRuntimeProvenancePurposeV1::InrouHostWithdraw,
                        &provenance_preimage,
                    )
                    .map_err(|error| {
                        eyre::eyre!(
                            "external signer refused Inrou host-withdrawal provenance: {error:?}"
                        )
                    })?,
            },
        });
        self.submit_instruction(
            instruction,
            "/internal/soracloud/runtime/inrou-host-withdraw",
        )
    }
}
fn build_soracloud_runtime_submission_payload(
    network_id: iroha_data_model::NetworkId,
    authority: AccountId,
    instruction: InstructionBox,
    fee_payment: iroha_data_model::transaction::FeePaymentIntent,
    endpoint: &'static str,
) -> eyre::Result<TransactionPayload> {
    TransactionBuilder::new(network_id, authority, fee_payment)
        .with_instructions([instruction])
        .into_payload()
        .wrap_err_with(|| format!("build internal Soracloud runtime mutation at `{endpoint}`"))
}
#[cfg(test)]
fn sign_soracloud_runtime_submission_payload(
    payload: TransactionPayload,
    key_pair: &KeyPair,
    endpoint: &'static str,
) -> eyre::Result<SignedTransaction> {
    TransactionBuilder::from_payload(payload)
        .wrap_err_with(|| {
            format!("rebuild quoted internal Soracloud runtime mutation at `{endpoint}`")
        })?
        .try_sign(key_pair.private_key())
        .wrap_err_with(|| format!("sign internal Soracloud runtime mutation at `{endpoint}`"))
}
#[cfg(test)]
fn sign_soracloud_runtime_provenance(
    key_pair: &KeyPair,
    payload: &[u8],
    context: &'static str,
) -> eyre::Result<iroha_crypto::Signature> {
    iroha_crypto::Signature::try_new(key_pair.private_key(), payload).wrap_err(context)
}
fn current_host_inrou_guest_isa() -> SoraInrouGuestIsaV1 {
    #[cfg(target_arch = "x86_64")]
    {
        return SoraInrouGuestIsaV1::X8664;
    }
    #[cfg(target_arch = "aarch64")]
    {
        return SoraInrouGuestIsaV1::Aarch64;
    }
    #[allow(unreachable_code)]
    SoraInrouGuestIsaV1::Aarch64
}
fn portable_vm_guest_machine_profile(
    guest_isa: SoraInrouGuestIsaV1,
) -> PortableVmGuestMachineProfile {
    match guest_isa {
        SoraInrouGuestIsaV1::X8664 => PortableVmGuestMachineProfile {
            emulator_candidates: &["qemu-system-x86_64"],
            machine_type: "q35",
            serial_console: "ttyS0",
            root_label: "rootfs-x86_64",
            block_device: "virtio-blk-pci",
            net_device: "virtio-net-pci",
        },
        SoraInrouGuestIsaV1::Aarch64 => PortableVmGuestMachineProfile {
            emulator_candidates: &["qemu-system-aarch64"],
            machine_type: "virt",
            serial_console: "ttyAMA0",
            root_label: "rootfs-aarch64",
            block_device: "virtio-blk-device",
            net_device: "virtio-net-device",
        },
    }
}
#[cfg(not(target_os = "linux"))]
fn ensure_portable_vm_backend_available(
    config: &iroha_config::parameters::actual::SoracloudRuntimeInrou,
) -> eyre::Result<()> {
    let _ = config;
    eyre::bail!(
        "Inrou PortableVM release hosting requires Linux procfs identity attestation, anonymous QMP capabilities, and QEMU seccomp"
    )
}
#[cfg(not(target_os = "linux"))]
fn ensure_portable_vm_backend_statically_available(
    config: &iroha_config::parameters::actual::SoracloudRuntimeInrou,
) -> eyre::Result<()> {
    ensure_portable_vm_backend_available(config)
}
#[cfg(target_os = "linux")]
struct PortableVmBackendPreflight {
    child_identity: PortableVmChildIdentity,
    setpriv: PathBuf,
    shell: PathBuf,
    qemu: PathBuf,
}
#[cfg(target_os = "linux")]
fn portable_vm_backend_static_preflight(
    config: &iroha_config::parameters::actual::SoracloudRuntimeInrou,
) -> eyre::Result<PortableVmBackendPreflight> {
    let child_identity = portable_vm_child_identity(config)?;
    ensure_portable_vm_identity_reserved(&child_identity)
        .wrap_err("validate the locked local Inrou QEMU service identity")?;
    let setpriv = resolve_inrou_setpriv_executable().ok_or_else(|| {
        eyre::eyre!(
            "configured Inrou PortableVM backend requires root-owned `/usr/bin/setpriv` or `/bin/setpriv`"
        )
    })?;
    let shell = resolve_inrou_shell_executable().ok_or_else(|| {
        eyre::eyre!(
            "configured Inrou PortableVM backend requires root-owned `/bin/sh` or `/usr/bin/sh` for fail-closed descriptor cleanup"
        )
    })?;
    resolve_inrou_iptables_executable().ok_or_else(|| {
        eyre::eyre!(
            "configured Inrou PortableVM backend requires a root-owned iptables executable at a standard system path"
        )
    })?;
    resolve_inrou_ip6tables_executable().ok_or_else(|| {
        eyre::eyre!(
            "configured Inrou PortableVM backend requires a root-owned ip6tables executable at a standard system path"
        )
    })?;
    let profile = portable_vm_guest_machine_profile(current_host_inrou_guest_isa());
    let qemu = resolve_executable_candidates(profile.emulator_candidates).ok_or_else(|| {
        eyre::eyre!(
            "configured Inrou PortableVM backend requires one of {:?} on PATH",
            profile.emulator_candidates
        )
    })?;
    resolve_inrou_qemu_img_executable()
        .ok_or_else(|| eyre::eyre!("configured Inrou PortableVM backend requires qemu-img"))?;
    Ok(PortableVmBackendPreflight {
        child_identity,
        setpriv,
        shell,
        qemu,
    })
}
#[cfg(target_os = "linux")]
fn probe_portable_vm_backend(
    setpriv: &Path,
    shell: &Path,
    qemu: &Path,
    child_identity: &PortableVmChildIdentity,
) -> eyre::Result<()> {
    let output = run_inrou_qemu_command_capture_stdout_bounded(
        setpriv,
        shell,
        qemu,
        child_identity,
        &["-accel", "help"],
        SORACLOUD_INROU_BACKEND_PROBE_TIMEOUT,
        SORACLOUD_INROU_HOST_COMMAND_STDOUT_MAX_BYTES,
    )
    .wrap_err_with(|| format!("probe QEMU accelerators with {}", qemu.display()))?;
    let advertised = String::from_utf8_lossy(&output);
    let accelerator = "kvm";
    if !advertised.lines().any(|line| line.trim() == accelerator) {
        eyre::bail!(
            "configured PortableVM accelerator `{accelerator}` is not advertised by {}",
            qemu.display()
        );
    }
    run_inrou_qemu_command_capture_stdout_bounded(
        setpriv,
        shell,
        qemu,
        child_identity,
        &["-version"],
        SORACLOUD_INROU_BACKEND_PROBE_TIMEOUT,
        SORACLOUD_INROU_HOST_COMMAND_STDOUT_MAX_BYTES,
    )
    .wrap_err_with(|| {
        format!(
            "require QEMU seccomp sandbox support from {}",
            qemu.display()
        )
    })?;
    Ok(())
}
#[cfg(target_os = "linux")]
fn ensure_portable_vm_backend_available(
    config: &iroha_config::parameters::actual::SoracloudRuntimeInrou,
) -> eyre::Result<()> {
    let preflight = portable_vm_backend_static_preflight(config)?;
    let _single_instance_lock =
        acquire_inrou_iptables_lock().wrap_err("serialize the full Inrou QEMU startup probe")?;
    ensure_portable_vm_identity_reserved(&preflight.child_identity)
        .wrap_err("recheck the locked Inrou QEMU service identity under the global lock")?;
    ensure_no_process_with_inrou_identity(&preflight.child_identity)
        .wrap_err("require an exclusive Inrou QEMU identity before backend probes")?;
    probe_portable_vm_backend(
        &preflight.setpriv,
        &preflight.shell,
        &preflight.qemu,
        &preflight.child_identity,
    )?;
    ensure_no_process_with_inrou_identity(&preflight.child_identity)
        .wrap_err("require the startup QEMU probes to be fully reaped before advertisement")
}
#[cfg(target_os = "linux")]
fn ensure_portable_vm_backend_statically_available(
    config: &iroha_config::parameters::actual::SoracloudRuntimeInrou,
) -> eyre::Result<()> {
    portable_vm_backend_static_preflight(config).map(|_| ())
}
fn validate_configured_inrou_backend_shape(
    config: &iroha_config::parameters::actual::SoracloudRuntimeInrou,
) -> eyre::Result<()> {
    if !config.enabled {
        return Ok(());
    }
    if config.backends.is_empty() {
        eyre::bail!("enabled Inrou hosting requires a nonempty backend allowlist");
    }
    if config.backends.len() != 1
        || !config
            .backends
            .contains(&SoraInrouRuntimeBackendV1::PortableVm)
    {
        eyre::bail!("Inrou V1 runtime startup accepts only the `portable_vm` backend");
    }
    if config.max_concurrent_vms.get() != 1 {
        eyre::bail!(
            "Inrou PortableVM V1 requires max_concurrent_vms = 1 because its dedicated host identity is exclusive to one QEMU process"
        );
    }
    Ok(())
}
fn validate_soracloud_runtime_manager_posture(
    config: &SoracloudRuntimeManagerConfig,
) -> eyre::Result<()> {
    if config.inrou.enabled && !manager_allows_unconfined_inrou_for_tests(config) {
        eyre::bail!(
            "first-release iroha3d forbids Inrou hosting until PortableVM has mandatory mount, network, IPC, and MAC confinement"
        );
    }
    Ok(())
}
fn manager_allows_unconfined_inrou_for_tests(config: &SoracloudRuntimeManagerConfig) -> bool {
    #[cfg(test)]
    if config.allow_unconfined_inrou {
        return true;
    }
    let _ = config;
    false
}
fn ensure_configured_inrou_backends_available(
    config: &iroha_config::parameters::actual::SoracloudRuntimeInrou,
) -> eyre::Result<()> {
    validate_configured_inrou_backend_shape(config)?;
    if config.enabled {
        ensure_portable_vm_backend_available(config)
            .wrap_err("preflight configured PortableVM backend")?;
    }
    Ok(())
}
fn ensure_configured_inrou_backends_statically_available(
    config: &iroha_config::parameters::actual::SoracloudRuntimeInrou,
) -> eyre::Result<()> {
    validate_configured_inrou_backend_shape(config)?;
    if config.enabled {
        ensure_portable_vm_backend_statically_available(config)
            .wrap_err("statically revalidate configured PortableVM backend")?;
    }
    Ok(())
}
#[cfg(test)]
fn inrou_host_platform_supports_local_materialization() -> bool {
    let mut config = iroha_config::parameters::actual::SoracloudRuntimeInrou::default();
    config.enabled = true;
    config
        .backends
        .insert(SoraInrouRuntimeBackendV1::PortableVm);
    ensure_configured_inrou_backends_available(&config).is_ok()
}
#[derive(Clone, Debug, PartialEq, Eq)]
struct ModelHostViolationReportKey {
    validator_account_id: AccountId,
    kind: SoraModelHostViolationKindV1,
    placement_id: Option<Hash>,
}
impl ModelHostViolationReportKey {
    fn kind_sort_key(kind: SoraModelHostViolationKindV1) -> u8 {
        match kind {
            SoraModelHostViolationKindV1::WarmupNoShow => 0,
            SoraModelHostViolationKindV1::AssignedHeartbeatMiss => 1,
            SoraModelHostViolationKindV1::AdvertContradiction => 2,
        }
    }
}
impl PartialOrd for ModelHostViolationReportKey {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}
impl Ord for ModelHostViolationReportKey {
    fn cmp(&self, other: &Self) -> Ordering {
        self.validator_account_id
            .cmp(&other.validator_account_id)
            .then_with(|| Self::kind_sort_key(self.kind).cmp(&Self::kind_sort_key(other.kind)))
            .then_with(|| self.placement_id.cmp(&other.placement_id))
    }
}
fn bounded_cooldown_allows_attempt<K: Clone + Ord>(
    attempts_ms: &mut BTreeMap<K, u64>,
    key: &K,
    now_ms: u64,
    cooldown_ms: u64,
    max_entries: usize,
) -> bool {
    attempts_ms.retain(|_, attempted_at_ms| now_ms.saturating_sub(*attempted_at_ms) < cooldown_ms);
    if attempts_ms.contains_key(key) || attempts_ms.len() >= max_entries {
        return false;
    }
    attempts_ms.insert(key.clone(), now_ms);
    true
}
struct SoracloudModelHostViolationReporter {
    mutation_sink: Option<Arc<dyn SoracloudRuntimeMutationSink>>,
    recent_attempts_ms: Mutex<BTreeMap<ModelHostViolationReportKey, u64>>,
}
impl SoracloudModelHostViolationReporter {
    fn disabled() -> Arc<Self> {
        Arc::new(Self {
            mutation_sink: None,
            recent_attempts_ms: Mutex::new(BTreeMap::new()),
        })
    }
    fn with_mutation_sink(mutation_sink: Arc<dyn SoracloudRuntimeMutationSink>) -> Arc<Self> {
        Arc::new(Self {
            mutation_sink: Some(mutation_sink),
            recent_attempts_ms: Mutex::new(BTreeMap::new()),
        })
    }
    fn report(
        &self,
        view: &StateView<'_>,
        validator_account_id: &AccountId,
        kind: SoraModelHostViolationKindV1,
        placement_id: Option<Hash>,
        detail: Option<String>,
    ) {
        let Some(mutation_sink) = self.mutation_sink.as_ref() else {
            return;
        };
        let key = ModelHostViolationReportKey {
            validator_account_id: validator_account_id.clone(),
            kind,
            placement_id,
        };
        if self.authoritative_evidence_exists(view, &key) || !self.cooldown_allows_attempt(&key) {
            return;
        }
        let log_key = key.clone();
        let instruction = InstructionBox::from(isi::soracloud::ReportSoracloudModelHostViolation {
            validator_account_id: key.validator_account_id.clone(),
            kind: key.kind,
            placement_id: key.placement_id,
            detail,
        });
        if let Err(error) = mutation_sink.submit_instruction(
            instruction,
            "/internal/soracloud/runtime/model-host-violation",
        ) {
            iroha_logger::warn!(
                ?error,
                validator_account_id = %log_key.validator_account_id,
                kind = ?log_key.kind,
                placement_id = ?log_key.placement_id,
                "failed to submit Soracloud model-host violation from runtime health"
            );
            return;
        }
        if let Err(error) = mutation_sink.submit_instruction(
            InstructionBox::from(isi::soracloud::ReconcileSoracloudModelHosts),
            "/internal/soracloud/runtime/model-host-reconcile",
        ) {
            iroha_logger::warn!(
                ?error,
                validator_account_id = %log_key.validator_account_id,
                kind = ?log_key.kind,
                placement_id = ?log_key.placement_id,
                "failed to submit Soracloud model-host reconcile after runtime health report"
            );
        }
    }
    fn authoritative_evidence_exists(
        &self,
        view: &StateView<'_>,
        key: &ModelHostViolationReportKey,
    ) -> bool {
        view.world()
            .soracloud_model_host_violation_evidence()
            .iter()
            .any(|(_evidence_id, record)| {
                record.validator_account_id == key.validator_account_id
                    && record.kind == key.kind
                    && record.placement_id == key.placement_id
            })
    }
    fn cooldown_allows_attempt(&self, key: &ModelHostViolationReportKey) -> bool {
        let now_ms = soracloud_runtime_observed_at_ms();
        let mut recent_attempts_ms = self.recent_attempts_ms.lock();
        bounded_cooldown_allows_attempt(
            &mut recent_attempts_ms,
            key,
            now_ms,
            MODEL_HOST_VIOLATION_REPORT_COOLDOWN_MS,
            SORACLOUD_COOLDOWN_TRACKER_MAX_ENTRIES,
        )
    }
}
impl SoracloudRuntimeManagerConfig {
    /// Build a runtime-manager configuration from the parsed Soracloud runtime settings.
    #[must_use]
    pub fn from_runtime_config(
        config: &iroha_config::parameters::actual::SoracloudRuntime,
    ) -> Self {
        config.assert_runtime_posture();
        Self {
            production_mode: config.production_mode,
            state_dir: config.state_dir.clone(),
            reconcile_interval: config.reconcile_interval,
            hydration_concurrency: config.hydration_concurrency,
            cache_budgets: config.cache_budgets.clone(),
            inrou: config.inrou.clone(),
            submission: config.submission.clone(),
            egress: config.egress.clone(),
            hf: config.hf.clone(),
            local_validator_account_id: None,
            local_peer_id: None,
            #[cfg(test)]
            allow_unconfined_inrou: false,
        }
    }
    /// Attach the local host identity used for placement-aware HF execution.
    #[must_use]
    pub fn with_local_host_identity(
        mut self,
        validator_account_id: AccountId,
        peer_id: impl Into<String>,
    ) -> Self {
        self.local_validator_account_id = Some(validator_account_id);
        self.local_peer_id = Some(peer_id.into());
        self
    }
}
#[derive(Clone, Debug, PartialEq, Eq)]
struct SoracloudArtifactFileFingerprint {
    bytes: u64,
    #[cfg(unix)]
    device: u64,
    #[cfg(unix)]
    inode: u64,
    #[cfg(unix)]
    modified_seconds: i64,
    #[cfg(unix)]
    modified_nanoseconds: i64,
    #[cfg(unix)]
    changed_seconds: i64,
    #[cfg(unix)]
    changed_nanoseconds: i64,
    #[cfg(not(unix))]
    modified_nanoseconds: Option<u128>,
}
impl SoracloudArtifactFileFingerprint {
    fn from_metadata(
        metadata: &fs::Metadata,
        cache_path: &Path,
    ) -> Result<Self, SoracloudRuntimeExecutionError> {
        if !metadata.is_file() {
            return Err(SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Internal,
                format!(
                    "hydrated Soracloud artifact cache {} is not a regular file",
                    cache_path.display()
                ),
            ));
        }
        #[cfg(unix)]
        if metadata.nlink() != 1 {
            return Err(SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Internal,
                format!(
                    "hydrated Soracloud artifact cache {} must have exactly one hard link, found {}",
                    cache_path.display(),
                    metadata.nlink()
                ),
            ));
        }
        Ok(Self {
            bytes: metadata.len(),
            #[cfg(unix)]
            device: metadata.dev(),
            #[cfg(unix)]
            inode: metadata.ino(),
            #[cfg(unix)]
            modified_seconds: metadata.mtime(),
            #[cfg(unix)]
            modified_nanoseconds: metadata.mtime_nsec(),
            #[cfg(unix)]
            changed_seconds: metadata.ctime(),
            #[cfg(unix)]
            changed_nanoseconds: metadata.ctime_nsec(),
            #[cfg(not(unix))]
            modified_nanoseconds: metadata
                .modified()
                .ok()
                .and_then(|modified| modified.duration_since(std::time::UNIX_EPOCH).ok())
                .map(|duration| duration.as_nanos()),
        })
    }
}
fn open_soracloud_artifact_for_validation(
    cache_path: &Path,
) -> Result<(fs::File, SoracloudArtifactFileFingerprint), SoracloudRuntimeExecutionError> {
    let named_metadata = fs::symlink_metadata(cache_path).map_err(|error| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "inspect hydrated Soracloud artifact cache {} before opening: {error}",
                cache_path.display()
            ),
        )
    })?;
    let named_fingerprint =
        SoracloudArtifactFileFingerprint::from_metadata(&named_metadata, cache_path)?;
    let mut options = fs::OpenOptions::new();
    options.read(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt as _;
        options.custom_flags(rustix::fs::OFlags::NOFOLLOW.bits() as i32);
    }
    #[cfg(windows)]
    {
        use std::os::windows::fs::OpenOptionsExt as _;
        const FILE_FLAG_OPEN_REPARSE_POINT: u32 = 0x0020_0000;
        options.custom_flags(FILE_FLAG_OPEN_REPARSE_POINT);
    }
    let file = options.open(cache_path).map_err(|error| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "open hydrated Soracloud artifact cache {} without following links: {error}",
                cache_path.display()
            ),
        )
    })?;
    let metadata = file.metadata().map_err(|error| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "inspect hydrated Soracloud artifact cache {}: {error}",
                cache_path.display()
            ),
        )
    })?;
    let fingerprint = SoracloudArtifactFileFingerprint::from_metadata(&metadata, cache_path)?;
    if fingerprint != named_fingerprint {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "hydrated Soracloud artifact cache {} changed identity while it was opened",
                cache_path.display()
            ),
        ));
    }
    Ok((file, fingerprint))
}
fn validate_opened_soracloud_artifact_after_read(
    file: &fs::File,
    cache_path: &Path,
    expected_fingerprint: &SoracloudArtifactFileFingerprint,
    observed_bytes: u64,
) -> Result<(), SoracloudRuntimeExecutionError> {
    let opened_metadata = file.metadata().map_err(|error| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "reinspect opened hydrated Soracloud artifact cache {}: {error}",
                cache_path.display()
            ),
        )
    })?;
    let named_metadata = fs::symlink_metadata(cache_path).map_err(|error| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "reinspect named hydrated Soracloud artifact cache {}: {error}",
                cache_path.display()
            ),
        )
    })?;
    let opened_fingerprint =
        SoracloudArtifactFileFingerprint::from_metadata(&opened_metadata, cache_path)?;
    let named_fingerprint =
        SoracloudArtifactFileFingerprint::from_metadata(&named_metadata, cache_path)?;
    if &opened_fingerprint != expected_fingerprint
        || named_fingerprint != opened_fingerprint
        || opened_fingerprint.bytes != observed_bytes
    {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "hydrated Soracloud artifact cache {} changed while it was being read",
                cache_path.display()
            ),
        ));
    }
    Ok(())
}
fn read_opened_soracloud_artifact_bounded(
    mut file: fs::File,
    cache_path: &Path,
    fingerprint: &SoracloudArtifactFileFingerprint,
    maximum_bytes: u64,
) -> Result<Vec<u8>, SoracloudRuntimeExecutionError> {
    if fingerprint.bytes > maximum_bytes {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            format!(
                "hydrated Soracloud artifact cache {} requires {} bytes, exceeding the configured {maximum_bytes}-byte limit",
                cache_path.display(),
                fingerprint.bytes
            ),
        ));
    }
    let capacity = usize::try_from(fingerprint.bytes).map_err(|_| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            format!(
                "hydrated Soracloud artifact cache {} is too large to address",
                cache_path.display()
            ),
        )
    })?;
    let mut bytes = Vec::with_capacity(capacity);
    io::Read::by_ref(&mut file)
        .take(maximum_bytes.saturating_add(1))
        .read_to_end(&mut bytes)
        .map_err(|error| {
            SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Unavailable,
                format!(
                    "read hydrated Soracloud artifact cache {}: {error}",
                    cache_path.display()
                ),
            )
        })?;
    let observed_bytes = u64::try_from(bytes.len()).map_err(|_| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            format!(
                "hydrated Soracloud artifact cache {} byte count does not fit u64",
                cache_path.display()
            ),
        )
    })?;
    if observed_bytes > maximum_bytes {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            format!(
                "hydrated Soracloud artifact cache {} exceeds the configured {maximum_bytes}-byte limit",
                cache_path.display()
            ),
        ));
    }
    validate_opened_soracloud_artifact_after_read(&file, cache_path, fingerprint, observed_bytes)?;
    Ok(bytes)
}
fn verify_cached_soracloud_artifact(
    cache_path: &Path,
    expected_hash: Hash,
    maximum_bytes: u64,
) -> Result<SoracloudArtifactFileFingerprint, SoracloudRuntimeExecutionError> {
    let (_file, fingerprint) =
        open_verified_cached_soracloud_artifact(cache_path, expected_hash, maximum_bytes)?;
    Ok(fingerprint)
}
fn open_verified_cached_soracloud_artifact(
    cache_path: &Path,
    expected_hash: Hash,
    maximum_bytes: u64,
) -> Result<(fs::File, SoracloudArtifactFileFingerprint), SoracloudRuntimeExecutionError> {
    let (mut file, fingerprint) = open_soracloud_artifact_for_validation(cache_path)?;
    if fingerprint.bytes > maximum_bytes {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            format!(
                "hydrated Soracloud artifact cache {} requires {} bytes, exceeding the configured {maximum_bytes}-byte limit",
                cache_path.display(),
                fingerprint.bytes
            ),
        ));
    }
    let (actual_hash, observed_bytes) = Hash::new_from_reader_bounded(&mut file, maximum_bytes)
        .map_err(|error| {
            SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Unavailable,
                format!(
                    "hash hydrated Soracloud artifact cache {}: {error}",
                    cache_path.display()
                ),
            )
        })?;
    validate_opened_soracloud_artifact_after_read(&file, cache_path, &fingerprint, observed_bytes)?;
    if actual_hash != expected_hash {
        return Err(SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Internal,
            format!(
                "hydrated Soracloud artifact cache {} failed hash verification: expected {}, found {}",
                cache_path.display(),
                expected_hash,
                actual_hash
            ),
        ));
    }
    file.rewind().map_err(|error| {
        SoracloudRuntimeExecutionError::new(
            SoracloudRuntimeExecutionErrorKind::Unavailable,
            format!(
                "rewind verified Soracloud artifact cache {}: {error}",
                cache_path.display()
            ),
        )
    })?;
    Ok((file, fingerprint))
}
#[derive(Default)]
struct SoracloudPreparedRuntimeCounters {
    metadata_validations: AtomicU64,
    artifact_reads: AtomicU64,
    artifact_hashes: AtomicU64,
    contract_preparations: AtomicU64,
    runtime_allocations: AtomicU64,
    prepared_loads: AtomicU64,
    template_builds: AtomicU64,
    runtime_reuses: AtomicU64,
    dirty_resets: AtomicU64,
    runtime_returns: AtomicU64,
    invalidations: AtomicU64,
    evictions: AtomicU64,
}
impl SoracloudPreparedRuntimeCounters {
    fn increment(counter: &AtomicU64) {
        let _ = counter.fetch_update(AtomicOrdering::Relaxed, AtomicOrdering::Relaxed, |value| {
            Some(value.saturating_add(1))
        });
    }
}
struct PooledSoracloudIvm {
    vm: IVM,
    previously_used: bool,
}
struct SoracloudPreparedContractEntry {
    cache_path: PathBuf,
    fingerprint: SoracloudArtifactFileFingerprint,
    prepared: PreparedContract,
    template: Arc<RuntimeTemplate>,
    idle_runtimes: Vec<PooledSoracloudIvm>,
    artifact_bytes: u64,
    generation: u64,
    last_used: u64,
}
#[derive(Clone)]
struct CachedSoracloudPreparedContract {
    key: Hash,
    generation: u64,
    prepared: PreparedContract,
    template: Arc<RuntimeTemplate>,
}
impl CachedSoracloudPreparedContract {
    fn entrypoint_pc(&self, name: &str) -> Option<u64> {
        self.prepared.entrypoint_pc(name)
    }
}
#[derive(Default)]
struct SoracloudPreparedRuntimeCacheState {
    entries: BTreeMap<Hash, SoracloudPreparedContractEntry>,
    retained_artifact_bytes: u64,
    idle_runtimes: usize,
    clock: u64,
    next_generation: u64,
}
impl SoracloudPreparedRuntimeCacheState {
    fn next_tick(&mut self) -> u64 {
        self.clock = self.clock.saturating_add(1);
        self.clock
    }
    fn next_generation(&mut self) -> u64 {
        self.next_generation = self.next_generation.saturating_add(1);
        self.next_generation
    }
    fn remove_entry(&mut self, key: &Hash) -> bool {
        let Some(entry) = self.entries.remove(key) else {
            return false;
        };
        self.retained_artifact_bytes = self
            .retained_artifact_bytes
            .saturating_sub(entry.artifact_bytes);
        self.idle_runtimes = self.idle_runtimes.saturating_sub(entry.idle_runtimes.len());
        true
    }
    fn least_recently_used_entry(&self, excluding: Option<Hash>) -> Option<Hash> {
        self.entries
            .iter()
            .filter(|(key, _)| excluding.as_ref().is_none_or(|excluded| *key != excluded))
            .min_by_key(|(_, entry)| entry.last_used)
            .map(|(key, _)| *key)
    }
    fn least_recently_used_idle_runtime_entry(&self) -> Option<Hash> {
        self.entries
            .iter()
            .filter(|(_, entry)| !entry.idle_runtimes.is_empty())
            .min_by_key(|(_, entry)| entry.last_used)
            .map(|(key, _)| *key)
    }
}
struct SoracloudPreparedRuntimeCache {
    state: Mutex<SoracloudPreparedRuntimeCacheState>,
    max_prepared_artifact_bytes: u64,
    max_idle_runtimes: usize,
    counters: SoracloudPreparedRuntimeCounters,
}
impl SoracloudPreparedRuntimeCache {
    fn new(max_prepared_artifact_bytes: u64, max_idle_runtimes: NonZeroUsize) -> Self {
        Self {
            state: Mutex::new(SoracloudPreparedRuntimeCacheState::default()),
            max_prepared_artifact_bytes,
            max_idle_runtimes: max_idle_runtimes.get(),
            counters: SoracloudPreparedRuntimeCounters::default(),
        }
    }
    fn from_config(config: &SoracloudRuntimeManagerConfig) -> Self {
        Self::new(
            config.cache_budgets.bundle_bytes.get(),
            config.hydration_concurrency,
        )
    }
    fn invalidate(&self, key: Hash) {
        if self.state.lock().remove_entry(&key) {
            SoracloudPreparedRuntimeCounters::increment(&self.counters.invalidations);
        }
    }
    fn enforce_idle_runtime_limit(&self, state: &mut SoracloudPreparedRuntimeCacheState) {
        while state.idle_runtimes > self.max_idle_runtimes {
            let Some(key) = state.least_recently_used_idle_runtime_entry() else {
                break;
            };
            let Some(entry) = state.entries.get_mut(&key) else {
                break;
            };
            if entry.idle_runtimes.pop().is_some() {
                state.idle_runtimes = state.idle_runtimes.saturating_sub(1);
                SoracloudPreparedRuntimeCounters::increment(&self.counters.evictions);
            }
        }
    }
    fn cached_handle(
        key: Hash,
        entry: &SoracloudPreparedContractEntry,
    ) -> CachedSoracloudPreparedContract {
        CachedSoracloudPreparedContract {
            key,
            generation: entry.generation,
            prepared: entry.prepared.clone(),
            template: Arc::clone(&entry.template),
        }
    }
    fn prepare(
        &self,
        cache_path: &Path,
        expected_hash: Hash,
    ) -> Result<CachedSoracloudPreparedContract, SoracloudRuntimeExecutionError> {
        SoracloudPreparedRuntimeCounters::increment(&self.counters.metadata_validations);
        let (file, fingerprint) = match open_soracloud_artifact_for_validation(cache_path) {
            Ok(opened) => opened,
            Err(error) => {
                self.invalidate(expected_hash);
                return Err(error);
            }
        };
        if fingerprint.bytes > self.max_prepared_artifact_bytes {
            self.invalidate(expected_hash);
            return Err(SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Internal,
                format!(
                    "hydrated Soracloud artifact cache {} requires {} bytes, exceeding the configured {}-byte prepared-contract budget",
                    cache_path.display(),
                    fingerprint.bytes,
                    self.max_prepared_artifact_bytes
                ),
            ));
        }
        {
            let mut state = self.state.lock();
            let is_hit = state.entries.get(&expected_hash).is_some_and(|entry| {
                entry.cache_path == cache_path && entry.fingerprint == fingerprint
            });
            if is_hit {
                let tick = state.next_tick();
                let entry = state
                    .entries
                    .get_mut(&expected_hash)
                    .expect("matching prepared entry must exist");
                entry.last_used = tick;
                return Ok(Self::cached_handle(expected_hash, entry));
            }
            if state.remove_entry(&expected_hash) {
                SoracloudPreparedRuntimeCounters::increment(&self.counters.invalidations);
            }
        }
        SoracloudPreparedRuntimeCounters::increment(&self.counters.artifact_reads);
        let artifact = read_opened_soracloud_artifact_bounded(
            file,
            cache_path,
            &fingerprint,
            self.max_prepared_artifact_bytes,
        )?;
        SoracloudPreparedRuntimeCounters::increment(&self.counters.artifact_hashes);
        let actual_hash = Hash::new(&artifact);
        if actual_hash != expected_hash {
            return Err(SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Internal,
                format!(
                    "hydrated Soracloud artifact cache {} failed hash verification: expected {}, found {}",
                    cache_path.display(),
                    expected_hash,
                    actual_hash
                ),
            ));
        }
        let artifact_bytes = fingerprint.bytes;
        let prepared =
            prepare_contract(Arc::<[u8]>::from(artifact.into_boxed_slice())).map_err(|error| {
                SoracloudRuntimeExecutionError::new(
                    SoracloudRuntimeExecutionErrorKind::Internal,
                    format!(
                        "verify and prepare Soracloud contract artifact {}: {error}",
                        cache_path.display()
                    ),
                )
            })?;
        SoracloudPreparedRuntimeCounters::increment(&self.counters.contract_preparations);
        let mut vm = IVM::new(u64::MAX);
        SoracloudPreparedRuntimeCounters::increment(&self.counters.runtime_allocations);
        vm.load_prepared(&prepared).map_err(|error| {
            SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Internal,
                format!(
                    "load prepared Soracloud contract artifact {}: {}",
                    cache_path.display(),
                    vm_error_label(&error)
                ),
            )
        })?;
        SoracloudPreparedRuntimeCounters::increment(&self.counters.prepared_loads);
        let template = Arc::new(vm.runtime_template());
        SoracloudPreparedRuntimeCounters::increment(&self.counters.template_builds);
        // The descriptor used for the read must still name the file that was
        // hashed. A replacement between read and insertion is invalidated and
        // retried by the caller on its next request.
        SoracloudPreparedRuntimeCounters::increment(&self.counters.metadata_validations);
        let (_, current_fingerprint) = open_soracloud_artifact_for_validation(cache_path)?;
        if current_fingerprint != fingerprint {
            return Err(SoracloudRuntimeExecutionError::new(
                SoracloudRuntimeExecutionErrorKind::Unavailable,
                format!(
                    "hydrated Soracloud artifact cache {} changed while it was being prepared",
                    cache_path.display()
                ),
            ));
        }
        let mut state = self.state.lock();
        if state.remove_entry(&expected_hash) {
            SoracloudPreparedRuntimeCounters::increment(&self.counters.invalidations);
        }
        while state.retained_artifact_bytes.saturating_add(artifact_bytes)
            > self.max_prepared_artifact_bytes
        {
            let Some(evicted) = state.least_recently_used_entry(Some(expected_hash)) else {
                break;
            };
            if state.remove_entry(&evicted) {
                SoracloudPreparedRuntimeCounters::increment(&self.counters.evictions);
            }
        }
        let generation = state.next_generation();
        let last_used = state.next_tick();
        state.retained_artifact_bytes =
            state.retained_artifact_bytes.saturating_add(artifact_bytes);
        state.idle_runtimes = state.idle_runtimes.saturating_add(1);
        state.entries.insert(
            expected_hash,
            SoracloudPreparedContractEntry {
                cache_path: cache_path.to_path_buf(),
                fingerprint,
                prepared: prepared.clone(),
                template: Arc::clone(&template),
                idle_runtimes: vec![PooledSoracloudIvm {
                    vm,
                    previously_used: false,
                }],
                artifact_bytes,
                generation,
                last_used,
            },
        );
        self.enforce_idle_runtime_limit(&mut state);
        let entry = state
            .entries
            .get(&expected_hash)
            .expect("new prepared entry must remain within its own byte budget");
        Ok(Self::cached_handle(expected_hash, entry))
    }
    fn checkout<'cache>(
        &'cache self,
        prepared: &CachedSoracloudPreparedContract,
    ) -> Result<SoracloudIvmRuntimeLease<'cache>, SoracloudRuntimeExecutionError> {
        let pooled = {
            let mut state = self.state.lock();
            let tick = state.next_tick();
            let pooled = state
                .entries
                .get_mut(&prepared.key)
                .filter(|entry| entry.generation == prepared.generation)
                .and_then(|entry| {
                    entry.last_used = tick;
                    entry.idle_runtimes.pop()
                });
            if pooled.is_some() {
                state.idle_runtimes = state.idle_runtimes.saturating_sub(1);
            }
            pooled
        };
        let vm = if let Some(pooled) = pooled {
            if pooled.previously_used {
                SoracloudPreparedRuntimeCounters::increment(&self.counters.runtime_reuses);
            }
            pooled.vm
        } else {
            let mut vm = IVM::new(u64::MAX);
            SoracloudPreparedRuntimeCounters::increment(&self.counters.runtime_allocations);
            vm.load_prepared(&prepared.prepared).map_err(|error| {
                SoracloudRuntimeExecutionError::new(
                    SoracloudRuntimeExecutionErrorKind::Internal,
                    format!(
                        "load cached prepared Soracloud contract: {}",
                        vm_error_label(&error)
                    ),
                )
            })?;
            SoracloudPreparedRuntimeCounters::increment(&self.counters.prepared_loads);
            vm
        };
        Ok(SoracloudIvmRuntimeLease {
            cache: self,
            key: prepared.key,
            generation: prepared.generation,
            template: Arc::clone(&prepared.template),
            vm: Some(vm),
        })
    }
    fn return_runtime(&self, key: Hash, generation: u64, vm: IVM) {
        let mut state = self.state.lock();
        let tick = state.next_tick();
        let Some(entry) = state
            .entries
            .get_mut(&key)
            .filter(|entry| entry.generation == generation)
        else {
            SoracloudPreparedRuntimeCounters::increment(&self.counters.evictions);
            return;
        };
        entry.last_used = tick;
        entry.idle_runtimes.push(PooledSoracloudIvm {
            vm,
            previously_used: true,
        });
        state.idle_runtimes = state.idle_runtimes.saturating_add(1);
        SoracloudPreparedRuntimeCounters::increment(&self.counters.runtime_returns);
        self.enforce_idle_runtime_limit(&mut state);
    }
    #[cfg(test)]
    fn stats(&self) -> SoracloudPreparedRuntimeStats {
        let state = self.state.lock();
        SoracloudPreparedRuntimeStats {
            metadata_validations: self
                .counters
                .metadata_validations
                .load(AtomicOrdering::Relaxed),
            artifact_reads: self.counters.artifact_reads.load(AtomicOrdering::Relaxed),
            artifact_hashes: self.counters.artifact_hashes.load(AtomicOrdering::Relaxed),
            contract_preparations: self
                .counters
                .contract_preparations
                .load(AtomicOrdering::Relaxed),
            runtime_allocations: self
                .counters
                .runtime_allocations
                .load(AtomicOrdering::Relaxed),
            prepared_loads: self.counters.prepared_loads.load(AtomicOrdering::Relaxed),
            template_builds: self.counters.template_builds.load(AtomicOrdering::Relaxed),
            runtime_reuses: self.counters.runtime_reuses.load(AtomicOrdering::Relaxed),
            dirty_resets: self.counters.dirty_resets.load(AtomicOrdering::Relaxed),
            runtime_returns: self.counters.runtime_returns.load(AtomicOrdering::Relaxed),
            invalidations: self.counters.invalidations.load(AtomicOrdering::Relaxed),
            evictions: self.counters.evictions.load(AtomicOrdering::Relaxed),
            prepared_entries: state.entries.len(),
            retained_artifact_bytes: state.retained_artifact_bytes,
            idle_runtimes: state.idle_runtimes,
        }
    }
}
struct SoracloudIvmRuntimeLease<'cache> {
    cache: &'cache SoracloudPreparedRuntimeCache,
    key: Hash,
    generation: u64,
    template: Arc<RuntimeTemplate>,
    vm: Option<IVM>,
}
impl Deref for SoracloudIvmRuntimeLease<'_> {
    type Target = IVM;
    fn deref(&self) -> &Self::Target {
        self.vm.as_ref().expect("runtime lease must own an IVM")
    }
}
impl DerefMut for SoracloudIvmRuntimeLease<'_> {
    fn deref_mut(&mut self) -> &mut Self::Target {
        self.vm.as_mut().expect("runtime lease must own an IVM")
    }
}
impl Drop for SoracloudIvmRuntimeLease<'_> {
    fn drop(&mut self) {
        let Some(mut vm) = self.vm.take() else {
            return;
        };
        if vm.reset_from_runtime_template(&self.template).is_err() {
            return;
        }
        SoracloudPreparedRuntimeCounters::increment(&self.cache.counters.dirty_resets);
        self.cache.return_runtime(self.key, self.generation, vm);
    }
}
#[cfg(test)]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct SoracloudPreparedRuntimeStats {
    metadata_validations: u64,
    artifact_reads: u64,
    artifact_hashes: u64,
    contract_preparations: u64,
    runtime_allocations: u64,
    prepared_loads: u64,
    template_builds: u64,
    runtime_reuses: u64,
    dirty_resets: u64,
    runtime_returns: u64,
    invalidations: u64,
    evictions: u64,
    prepared_entries: usize,
    retained_artifact_bytes: u64,
    idle_runtimes: usize,
}
/// Executable handle to the embedded Soracloud runtime manager.
#[derive(Clone)]
pub struct SoracloudRuntimeManagerHandle {
    snapshot: Arc<RwLock<SoracloudRuntimeSnapshot>>,
    config: Arc<SoracloudRuntimeManagerConfig>,
    state_dir: Arc<PathBuf>,
    state: Arc<State>,
    hf_local_workers: SharedHfLocalRunnerWorkers,
    host_violation_reporter: Arc<SoracloudModelHostViolationReporter>,
    mutation_sink: Option<Arc<dyn SoracloudRuntimeMutationSink>>,
    hf_inference_credential_provider:
        Option<Arc<dyn crate::soracloud_hf_credential::SoracloudHfInferenceCredentialProviderV1>>,
    generated_hf_reconcile_attempts_ms: Arc<Mutex<BTreeMap<Hash, u64>>>,
    ivm_runtime_cache: Arc<SoracloudPreparedRuntimeCache>,
}
impl SoracloudRuntimeManagerHandle {
    /// Return the latest materialization snapshot.
    #[must_use]
    pub fn snapshot(&self) -> SoracloudRuntimeSnapshot {
        self.snapshot.read().clone()
    }
    /// Return the runtime-manager state directory.
    #[must_use]
    pub fn state_dir(&self) -> PathBuf {
        self.state_dir.as_ref().clone()
    }
    #[cfg(test)]
    fn ivm_runtime_cache_stats(&self) -> SoracloudPreparedRuntimeStats {
        self.ivm_runtime_cache.stats()
    }
    fn report_generated_hf_proxy_failure(
        &self,
        request: &SoracloudLocalReadRequest,
        target_peer_id: &str,
        error: &SoracloudRuntimeExecutionError,
    ) {
        if request.handler_name != "infer"
            || error.kind == SoracloudRuntimeExecutionErrorKind::InvalidRequest
        {
            return;
        }
        let view = self.state.view();
        let Some(bundle) = view.world().soracloud_service_revisions().get(&(
            request.service_name.clone(),
            request.service_version.clone(),
        )) else {
            return;
        };
        let Some(binding) = soracloud_hf_generated_source_binding(bundle) else {
            return;
        };
        let Ok(Some(placement)) = resolve_active_hf_placement_for_service(
            &view,
            request.service_name.as_str(),
            &binding.source_id,
        ) else {
            return;
        };
        let Some(primary_assignment) = placement.assigned_hosts.iter().find(|assignment| {
            assignment.role == SoraHfPlacementHostRoleV1::Primary
                && assignment.status == SoraHfPlacementHostStatusV1::Warm
                && assignment.peer_id == target_peer_id
        }) else {
            return;
        };
        self.host_violation_reporter.report(
            &view,
            &primary_assignment.validator_account_id,
            SoraModelHostViolationKindV1::AssignedHeartbeatMiss,
            Some(placement.placement_id),
            Some(format!(
                "proxied HF inference for service `{}` targeting primary peer `{target_peer_id}` failed: {}",
                request.service_name, error.message
            )),
        );
    }
    fn report_generated_hf_local_proxy_failure(
        &self,
        request: &SoracloudLocalReadRequest,
        error: &SoracloudRuntimeExecutionError,
    ) {
        if request.handler_name != "infer"
            || error.kind == SoracloudRuntimeExecutionErrorKind::InvalidRequest
        {
            return;
        }
        let view = self.state.view();
        let Some(bundle) = view.world().soracloud_service_revisions().get(&(
            request.service_name.clone(),
            request.service_version.clone(),
        )) else {
            return;
        };
        let Some(binding) = soracloud_hf_generated_source_binding(bundle) else {
            return;
        };
        let Ok(Some(placement)) = resolve_active_hf_placement_for_service(
            &view,
            request.service_name.as_str(),
            &binding.source_id,
        ) else {
            return;
        };
        let Some(local_assignment) = placement
            .assigned_hosts
            .iter()
            .find(|assignment| hf_assignment_matches_local_host(&self.config, assignment))
        else {
            return;
        };
        let kind = match local_assignment.status {
            SoraHfPlacementHostStatusV1::Warm => {
                SoraModelHostViolationKindV1::AssignedHeartbeatMiss
            }
            SoraHfPlacementHostStatusV1::Warming => SoraModelHostViolationKindV1::WarmupNoShow,
            SoraHfPlacementHostStatusV1::Unavailable | SoraHfPlacementHostStatusV1::Retired => {
                return;
            }
        };
        self.host_violation_reporter.report(
            &view,
            &local_assignment.validator_account_id,
            kind,
            Some(placement.placement_id),
            Some(format!(
                "local assigned {} peer `{}` failed to forward generated-HF proxy traffic for service `{}` before reaching the authoritative primary: {}",
                match local_assignment.role {
                    SoraHfPlacementHostRoleV1::Primary => "primary",
                    SoraHfPlacementHostRoleV1::Replica => "replica",
                },
                local_assignment.peer_id,
                request.service_name,
                error.message
            )),
        );
    }
    fn report_local_generated_hf_authority_failure(
        &self,
        view: &StateView<'_>,
        placement: &SoraHfPlacementRecordV1,
        request: &SoracloudLocalReadRequest,
        error: &SoracloudRuntimeExecutionError,
    ) -> bool {
        let Some(local_assignment) = placement
            .assigned_hosts
            .iter()
            .find(|assignment| hf_assignment_matches_local_host(&self.config, assignment))
        else {
            return false;
        };
        if local_assignment.role != SoraHfPlacementHostRoleV1::Primary {
            return false;
        }
        let kind = match local_assignment.status {
            SoraHfPlacementHostStatusV1::Warm => {
                SoraModelHostViolationKindV1::AssignedHeartbeatMiss
            }
            SoraHfPlacementHostStatusV1::Warming => SoraModelHostViolationKindV1::WarmupNoShow,
            SoraHfPlacementHostStatusV1::Unavailable | SoraHfPlacementHostStatusV1::Retired => {
                return false;
            }
        };
        self.host_violation_reporter.report(
            view,
            &local_assignment.validator_account_id,
            kind,
            Some(placement.placement_id),
            Some(format!(
                "local authoritative primary peer `{}` rejected generated-HF proxy execution for service `{}`: {}",
                local_assignment.peer_id, request.service_name, error.message
            )),
        );
        true
    }
    fn request_generated_hf_reconcile(
        &self,
        request: &SoracloudLocalReadRequest,
        error: &SoracloudRuntimeExecutionError,
    ) {
        if request.handler_name != "infer"
            || error.kind != SoracloudRuntimeExecutionErrorKind::Unavailable
        {
            return;
        }
        let Some(mutation_sink) = self.mutation_sink.as_ref() else {
            return;
        };
        let view = self.state.view();
        let Some(bundle) = view.world().soracloud_service_revisions().get(&(
            request.service_name.clone(),
            request.service_version.clone(),
        )) else {
            return;
        };
        let Some(binding) = soracloud_hf_generated_source_binding(bundle) else {
            return;
        };
        let Ok(Some(placement)) = resolve_active_hf_placement_for_service(
            &view,
            request.service_name.as_str(),
            &binding.source_id,
        ) else {
            return;
        };
        if self.report_local_generated_hf_authority_failure(&view, &placement, request, error) {
            return;
        }
        let has_warm_primary =
            iroha_core::soracloud_runtime::resolve_generated_hf_primary_assignment(
                view.world(),
                request.service_name.as_str(),
                &binding.source_id,
            )
            .ok()
            .flatten()
            .is_some();
        let local_assignment_present = placement
            .assigned_hosts
            .iter()
            .any(|assignment| hf_assignment_matches_local_host(&self.config, assignment));
        if has_warm_primary && !local_assignment_present {
            return;
        }
        if !self.generated_hf_reconcile_attempt_allowed(placement.placement_id) {
            return;
        }
        if let Err(submit_error) = mutation_sink.submit_instruction(
            InstructionBox::from(isi::soracloud::ReconcileSoracloudModelHosts),
            "/internal/soracloud/runtime/model-host-reconcile-hint",
        ) {
            iroha_logger::warn!(
                ?submit_error,
                placement_id = %placement.placement_id,
                service_name = %request.service_name,
                service_version = %request.service_version,
                "failed to enqueue Soracloud model-host reconcile after generated-HF routing failure"
            );
        }
    }
    fn request_generated_hf_proxy_responder_reconcile(
        &self,
        request: &SoracloudLocalReadRequest,
        responder_peer_id: &str,
        expected_peer_id: &str,
    ) {
        if request.handler_name != "infer" || responder_peer_id == expected_peer_id {
            return;
        }
        if self.mutation_sink.is_none() {
            return;
        }
        let view = self.state.view();
        let Some(bundle) = view.world().soracloud_service_revisions().get(&(
            request.service_name.clone(),
            request.service_version.clone(),
        )) else {
            return;
        };
        let Some(binding) = soracloud_hf_generated_source_binding(bundle) else {
            return;
        };
        let Ok(Some(placement)) = resolve_active_hf_placement_for_service(
            &view,
            request.service_name.as_str(),
            &binding.source_id,
        ) else {
            return;
        };
        let Some(unexpected_assignment) = placement.assigned_hosts.iter().find(|assignment| {
            assignment.peer_id == responder_peer_id
                && assignment.status != SoraHfPlacementHostStatusV1::Retired
        }) else {
            return;
        };
        let kind = match unexpected_assignment.status {
            SoraHfPlacementHostStatusV1::Warm | SoraHfPlacementHostStatusV1::Unavailable => {
                SoraModelHostViolationKindV1::AssignedHeartbeatMiss
            }
            SoraHfPlacementHostStatusV1::Warming => SoraModelHostViolationKindV1::WarmupNoShow,
            SoraHfPlacementHostStatusV1::Retired => return,
        };
        self.host_violation_reporter.report(
            &view,
            &unexpected_assignment.validator_account_id,
            kind,
            Some(placement.placement_id),
            Some(format!(
                "assigned {} peer `{}` answered a generated-HF proxy response for service `{}` even though authoritative primary peer is `{expected_peer_id}`",
                match unexpected_assignment.role {
                    SoraHfPlacementHostRoleV1::Primary => "primary",
                    SoraHfPlacementHostRoleV1::Replica => "replica",
                },
                responder_peer_id,
                request.service_name,
            )),
        );
    }
    fn generated_hf_reconcile_attempt_allowed(&self, placement_id: Hash) -> bool {
        let now_ms = soracloud_runtime_observed_at_ms();
        let mut attempts = self.generated_hf_reconcile_attempts_ms.lock();
        bounded_cooldown_allows_attempt(
            &mut attempts,
            &placement_id,
            now_ms,
            GENERATED_HF_RECONCILE_REQUEST_COOLDOWN_MS,
            SORACLOUD_COOLDOWN_TRACKER_MAX_ENTRIES,
        )
    }
}
fn uploaded_model_encryption_key_dir(state_dir: &Path) -> PathBuf {
    state_dir.join(SORACLOUD_UPLOADED_MODEL_UPLOAD_KEY_DIR)
}
fn generate_uploaded_model_encryption_secret_with_rng<R: TryCryptoRng>(
    rng: &mut R,
) -> io::Result<[u8; 32]> {
    let mut secret_bytes = [0_u8; 32];
    rng.try_fill_bytes(&mut secret_bytes).map_err(|error| {
        io::Error::other(format!(
            "uploaded model encryption key OS RNG failed: {error}"
        ))
    })?;
    if secret_bytes.iter().all(|byte| *byte == secret_bytes[0]) {
        return Err(io::Error::other(
            "uploaded model encryption key OS RNG returned degenerate output",
        ));
    }
    Ok(X25519StaticSecret::from(secret_bytes).to_bytes())
}

#[cfg(unix)]
fn prepare_uploaded_model_encryption_key_dir(path: &Path) -> io::Result<PathBuf> {
    use std::os::unix::fs::{DirBuilderExt as _, OpenOptionsExt as _};

    let mut builder = fs::DirBuilder::new();
    builder.recursive(true).mode(0o700);
    builder.create(path)?;

    let named = fs::symlink_metadata(path)?;
    if named.file_type().is_symlink() || !named.is_dir() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "uploaded model encryption key directory {} must be a real directory",
                path.display()
            ),
        ));
    }
    let effective_uid = rustix::process::geteuid().as_raw();
    if named.uid() != effective_uid || named.mode() & 0o077 != 0 {
        return Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            format!(
                "uploaded model encryption key directory {} must be runtime-owned and owner-private",
                path.display()
            ),
        ));
    }

    let canonical = fs::canonicalize(path)?;
    for (index, ancestor) in canonical.ancestors().enumerate() {
        let metadata = fs::metadata(ancestor)?;
        if !metadata.is_dir() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                format!(
                    "uploaded model encryption key ancestor {} must be a directory",
                    ancestor.display()
                ),
            ));
        }
        if metadata.uid() != 0 && metadata.uid() != effective_uid {
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                format!(
                    "uploaded model encryption key ancestor {} is not owned by root or the runtime uid {effective_uid}",
                    ancestor.display()
                ),
            ));
        }
        let replaceable = metadata.mode() & 0o022 != 0;
        let sticky = metadata.mode() & 0o1000 != 0;
        if replaceable && (index == 0 || !sticky) {
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                format!(
                    "uploaded model encryption key custody permits path replacement through {}",
                    ancestor.display()
                ),
            ));
        }
    }

    let directory = fs::OpenOptions::new()
        .read(true)
        .custom_flags(
            (rustix::fs::OFlags::NOFOLLOW
                | rustix::fs::OFlags::DIRECTORY
                | rustix::fs::OFlags::CLOEXEC)
                .bits() as i32,
        )
        .open(&canonical)?;
    let opened = directory.metadata()?;
    if opened.dev() != named.dev()
        || opened.ino() != named.ino()
        || opened.uid() != effective_uid
        || opened.mode() & 0o077 != 0
    {
        return Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            format!(
                "uploaded model encryption key directory {} changed or lost private custody while it was opened",
                path.display()
            ),
        ));
    }
    Ok(canonical)
}

#[cfg(not(unix))]
fn prepare_uploaded_model_encryption_key_dir(_path: &Path) -> io::Result<PathBuf> {
    Err(io::Error::new(
        io::ErrorKind::Unsupported,
        "uploaded model encryption keys require enforceable owner-private filesystem custody",
    ))
}

#[cfg(unix)]
fn read_uploaded_model_encryption_secret(path: &Path) -> io::Result<[u8; 32]> {
    let (mut file, fingerprint) =
        open_soracloud_regular_file_no_follow(path, "uploaded model encryption key")?;
    let effective_uid = rustix::process::geteuid().as_raw();
    if fingerprint.uid() != effective_uid || fingerprint.mode() & 0o077 != 0 {
        return Err(io::Error::new(
            io::ErrorKind::PermissionDenied,
            format!(
                "uploaded model encryption key {} must be runtime-owned and owner-private",
                path.display()
            ),
        ));
    }
    if fingerprint.len() != 32 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "uploaded model encryption key at `{}` must be exactly 32 bytes",
                path.display()
            ),
        ));
    }
    let mut bytes = [0_u8; 32];
    file.read_exact(&mut bytes)?;
    let mut trailing = [0_u8; 1];
    if file.read(&mut trailing)? != 0 {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "uploaded model encryption key at `{}` grew while it was read",
                path.display()
            ),
        ));
    }
    let opened_after = file.metadata()?;
    let named_after = fs::symlink_metadata(path)?;
    if !same_soracloud_regular_file(&fingerprint, &opened_after)
        || !same_soracloud_regular_file(&opened_after, &named_after)
    {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!(
                "uploaded model encryption key {} changed while it was read",
                path.display()
            ),
        ));
    }
    Ok(bytes)
}

#[cfg(not(unix))]
fn read_uploaded_model_encryption_secret(_path: &Path) -> io::Result<[u8; 32]> {
    Err(io::Error::new(
        io::ErrorKind::Unsupported,
        "uploaded model encryption keys require enforceable owner-private filesystem custody",
    ))
}

fn create_uploaded_model_encryption_key_staging_file(
    directory: &Path,
) -> io::Result<(PathBuf, fs::File)> {
    for _ in 0..128 {
        let mut suffix = [0_u8; 16];
        OsRng.try_fill_bytes(&mut suffix).map_err(|error| {
            io::Error::other(format!(
                "uploaded model encryption key staging OS RNG failed: {error}"
            ))
        })?;
        if suffix.iter().all(|byte| *byte == suffix[0]) {
            return Err(io::Error::other(
                "uploaded model encryption key staging OS RNG returned degenerate output",
            ));
        }
        let path = directory.join(format!(".x25519-v1-{}.tmp", hex::encode(suffix)));
        let mut options = fs::OpenOptions::new();
        options.read(true).write(true).create_new(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt as _;
            options.mode(0o600);
        }
        match options.open(&path) {
            Ok(file) => return Ok((path, file)),
            Err(error) if error.kind() == io::ErrorKind::AlreadyExists => {}
            Err(error) => return Err(error),
        }
    }
    Err(io::Error::new(
        io::ErrorKind::AlreadyExists,
        "exhausted exclusive uploaded model encryption key staging names",
    ))
}

fn remove_uploaded_model_encryption_key_staging_file(path: &Path, expected: &fs::Metadata) {
    let remove = fs::symlink_metadata(path).is_ok_and(|actual| {
        #[cfg(unix)]
        {
            actual.is_file() && actual.dev() == expected.dev() && actual.ino() == expected.ino()
        }
        #[cfg(not(unix))]
        {
            actual.is_file() && actual.len() == expected.len()
        }
    });
    if remove {
        let _ = fs::remove_file(path);
    }
}

fn same_uploaded_model_encryption_key_file(left: &fs::Metadata, right: &fs::Metadata) -> bool {
    #[cfg(unix)]
    {
        left.is_file() && right.is_file() && left.dev() == right.dev() && left.ino() == right.ino()
    }
    #[cfg(not(unix))]
    {
        left.is_file() && right.is_file()
    }
}

fn load_or_create_uploaded_model_encryption_secret(state_dir: &Path) -> io::Result<[u8; 32]> {
    let key_dir =
        prepare_uploaded_model_encryption_key_dir(&uploaded_model_encryption_key_dir(state_dir))?;
    let key_path = key_dir.join(SORACLOUD_UPLOADED_MODEL_UPLOAD_KEY_FILE);
    match read_uploaded_model_encryption_secret(&key_path) {
        Ok(bytes) => Ok(bytes),
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            let bytes = generate_uploaded_model_encryption_secret_with_rng(&mut OsRng)?;
            let (staging_path, mut staging) =
                create_uploaded_model_encryption_key_staging_file(&key_dir)?;
            let staging_identity = staging.metadata()?;
            let publish = (|| {
                staging.write_all(&bytes)?;
                staging.sync_all()?;
                let written = staging.metadata()?;
                if !same_uploaded_model_encryption_key_file(&staging_identity, &written)
                    || written.len() != 32
                {
                    return Err(io::Error::new(
                        io::ErrorKind::InvalidData,
                        "uploaded model encryption key staging file changed while it was written",
                    ));
                }
                #[cfg(unix)]
                if written.nlink() != 1
                    || written.uid() != rustix::process::geteuid().as_raw()
                    || written.mode() & 0o077 != 0
                {
                    return Err(io::Error::new(
                        io::ErrorKind::PermissionDenied,
                        "uploaded model encryption key staging file lost private custody",
                    ));
                }
                #[cfg(any(target_os = "linux", target_os = "android", target_vendor = "apple"))]
                match rustix::fs::renameat_with(
                    rustix::fs::CWD,
                    &staging_path,
                    rustix::fs::CWD,
                    &key_path,
                    rustix::fs::RenameFlags::NOREPLACE,
                ) {
                    Ok(()) => {}
                    Err(rustix::io::Errno::EXIST) => {
                        return Ok(false);
                    }
                    Err(error) => return Err(io::Error::from(error)),
                }
                #[cfg(not(any(
                    target_os = "linux",
                    target_os = "android",
                    target_vendor = "apple"
                )))]
                {
                    match fs::hard_link(&staging_path, &key_path) {
                        Ok(()) => fs::remove_file(&staging_path)?,
                        Err(error) if error.kind() == io::ErrorKind::AlreadyExists => {
                            return Ok(false);
                        }
                        Err(error) => return Err(error),
                    }
                }
                fs::File::open(&key_dir)?.sync_all()?;
                Ok(true)
            })();
            drop(staging);
            let published_new = match publish {
                Ok(true) => true,
                Ok(false) => {
                    remove_uploaded_model_encryption_key_staging_file(
                        &staging_path,
                        &staging_identity,
                    );
                    false
                }
                Err(error) => {
                    remove_uploaded_model_encryption_key_staging_file(
                        &staging_path,
                        &staging_identity,
                    );
                    return Err(error);
                }
            };
            let installed = read_uploaded_model_encryption_secret(&key_path)?;
            if published_new && installed != bytes {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidData,
                    "published uploaded model encryption key does not match the generated key",
                ));
            }
            Ok(installed)
        }
        Err(error) => Err(error),
    }
}
fn load_or_create_uploaded_model_encryption_recipient(
    state_dir: &Path,
) -> io::Result<SoracloudUploadedModelEncryptionRecipient> {
    let secret_bytes = load_or_create_uploaded_model_encryption_secret(state_dir)?;
    let secret = X25519StaticSecret::from(secret_bytes);
    let public_key_bytes = X25519PublicKey::from(&secret).to_bytes().to_vec();
    let public_key_fingerprint = Hash::new(public_key_bytes.as_slice());
    Ok(SoracloudUploadedModelEncryptionRecipient {
        schema_version: SORA_UPLOADED_MODEL_ENCRYPTION_RECIPIENT_VERSION_V1,
        key_id: format!(
            "soracloud-upload-x25519:{}",
            hex::encode(&public_key_bytes[..8])
        ),
        key_version: std::num::NonZeroU32::new(SORACLOUD_UPLOADED_MODEL_UPLOAD_KEY_VERSION_V1)
            .expect("non-zero upload key version"),
        kem: SoraUploadedModelKeyEncapsulationV1::X25519HkdfSha256,
        aead: SoraUploadedModelKeyWrapAeadV1::Aes256Gcm,
        public_key_bytes,
        public_key_fingerprint,
    })
}
