    fn ingest_operator_preseed_payload(
        store: &StorageBackend,
        plan: &CarBuildPlan,
        manifest: &sorafs_manifest::ManifestV1,
        payload: &[u8],
    ) -> Result<StoredManifest> {
        let mut reader = payload;
        let manifest_id = store.ingest_manifest(manifest, plan, &mut reader)?;
        store
            .manifest(&manifest_id)
            .ok_or_else(|| eyre::eyre!("ingested operator-preseed manifest is missing"))
    }
    fn build_sorafs_manifest(
        payload: &[u8],
    ) -> Result<(CarBuildPlan, sorafs_manifest::ManifestV1)> {
        let plan = CarBuildPlan::single_file(payload)?;
        let manifest = build_sorafs_manifest_from_plan(&plan, payload)?;
        Ok((plan, manifest))
    }
    fn build_sorafs_manifest_from_plan(
        plan: &CarBuildPlan,
        payload: &[u8],
    ) -> Result<sorafs_manifest::ManifestV1> {
        let stats = CarWriter::new(plan, payload)?.write_to(io::sink())?;
        let por_root = sorafs_car::compute_por_root(payload, plan)?;
        Ok(ManifestBuilder::new()
            .root_cid(
                stats
                    .root_cids
                    .first()
                    .cloned()
                    .ok_or_else(|| eyre::eyre!("fixture CAR writer produced no root CID"))?,
            )
            .dag_codec(DagCodecId(stats.dag_codec))
            .chunking_from_profile(plan.chunk_profile, BLAKE3_256_MULTIHASH_CODE)
            .chunk_digest_sha3_256(compute_chunk_plan_digest_sha3(&plan.chunks))
            .por_root(por_root)
            .content_length(plan.content_length)
            .car_digest(*stats.car_archive_digest.as_bytes())
            .car_size(stats.car_size)
            .pin_policy(ManifestPinPolicy {
                min_replicas: 1,
                storage_class: sorafs_manifest::StorageClass::Warm,
                retention_epoch: u64::MAX,
            })
            .build()?)
    }
    fn ingest_sorafs_payload(node: &NodeHandle, payload: &[u8]) -> Result<StoredManifest> {
        let (plan, manifest) = build_sorafs_manifest(payload)?;
        let mut reader = payload;
        let manifest_id = node.ingest_manifest(&manifest, &plan, &mut reader)?;
        node.manifest_metadata(&manifest_id).map_err(Into::into)
    }
    fn approve_sorafs_manifests(state: &Arc<State>, manifests: &[StoredManifest]) -> Result<()> {
        let view = state.view();
        let pricing = view.world().sorafs_pricing().clone();
        let next_height = NonZeroU64::new(
            u64::try_from(view.height())
                .unwrap_or(u64::MAX.saturating_sub(1))
                .saturating_add(1),
        )
        .expect("nonzero block height");
        let header = BlockHeader::new(next_height, view.latest_block_hash(), None, None, 0, 0);
        drop(view);
        let mut block = state.block(header);
        let mut pin_manifests = block.world.pin_manifests_mut_for_testing().transaction();
        for manifest in manifests {
            let canonical_manifest = manifest.load_manifest()?;
            let digest = ManifestDigest::new(*manifest.manifest_digest());
            let policy = PinPolicy::default();
            let submitted_epoch = 1;
            let content_length = canonical_manifest.content_length;
            let amount = pricing
                .public_pin_fee(
                    policy.storage_class,
                    content_length,
                    policy.min_replicas,
                    submitted_epoch,
                    policy.retention_epoch,
                )
                .wrap_err("compute SoraFS fixture pin fee")?;
            let mut record = PinManifestRecord::new(
                ManifestDigest::new(*manifest.manifest_digest()),
                ManifestRootCid::try_from_slice(manifest.manifest_cid())?,
                ChunkerProfileHandle {
                    profile_id: 1,
                    namespace: "sorafs".to_owned(),
                    name: "sf1".to_owned(),
                    semver: "1.0.0".to_owned(),
                    multihash_code: BLAKE3_256_MULTIHASH_CODE,
                },
                canonical_manifest.chunk_digest_sha3_256,
                canonical_manifest.por_root,
                content_length,
                policy,
                (*ALICE_ID).clone(),
                submitted_epoch,
                None,
                None,
                Metadata::default(),
            );
            record.record_pin_fee_payment(PinFeePayment {
                paid_by: (*ALICE_ID).clone(),
                fee_asset_id: state.gov.sorafs_pin_fee_asset_id.clone(),
                treasury_account_id: state.gov.sorafs_pin_fee_treasury_account.clone(),
                amount,
            });
            record.approve(submitted_epoch, None);
            pin_manifests.insert(digest, record);
        }
        pin_manifests.apply();
        block.commit()?;
        Ok(())
    }
